/**
 * Lib of js functions for booste
 *
 * @module     local_booste/helper
 * @copyright  2020 Mathew May <mathew.solutions>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define([
    'core/str',
    'core/ajax',
    'core/notification',
    'core/templates'
], function(Str, Ajax, Notification, Templates) {

    /**
     * Fetching verbs for the taxonomy choosen.
     *
     * @param {Number} taxonomyid
     */
    const fetchVerbs = (taxonomyid) => {
        const request = {
            methodname: 'local_booste_get_verbs',
            args: {taxonomyid: taxonomyid}
        };
        Ajax.call([request])[0].then(function(element) {
            document.getElementById('verbs_list').innerHTML = '';
            element.forEach(e => {
                document.getElementById('verbs_list').innerHTML +=
                    '<span class="badge badge-info mb-3 mr-1" style="font-size: 100%">' + e.name + '</span>';
            });
        }).catch(Notification.exception);
    };

    /**
     * Getting verbs for the taxonomy choosen.
     *
     * @param {Number} taxonomyid
     */
    const getVerbs = (taxonomyid) => {
        fetchVerbs(taxonomyid);
        document.querySelector('[name=taxonomy]').addEventListener('change', (event) => {
            fetchVerbs(event.target.value);
        });
        let objphrase = document.getElementById('objective_example_1').innerHTML;
        objphrase = objphrase.replaceAll('[', '<span class="objective-verb-1">[');
        objphrase = objphrase.replaceAll(']', ']</span>');
        document.getElementById('objective_example_1').innerHTML = objphrase;

        let objphrase2 = document.getElementById('objective_example_2').innerHTML;
        objphrase2 = objphrase2.replaceAll('[', '<span class="objective-verb-2">[');
        objphrase2 = objphrase2.replaceAll(']', ']</span>');
        document.getElementById('objective_example_2').innerHTML = objphrase2;
    };

    /**
     * Get string via get_string.
     *
     * @param {String} name
     * @return {Promise}
     */
    const getStringBooste = (name) => {
        return Str.get_string(name, 'local_booste');
    };

    /**
     * Get label of a string via get_string.
     *
     * @param {String} string
     * @return {Promise}
     */
    const getLabel = async(string) => {
        try {
            return await getStringBooste(string);
        } catch (e) {
            Notification.exception(e);
            return '';
        }
    };

    /**
     * Display helper of an activity.
     */
    const getActivityHelp = async() => {
        const helpers = document.querySelectorAll('[data-action=activity_helper]');
        helpers.forEach(helperEl => {
            helperEl.addEventListener('click', e => {
                e.preventDefault();
                const dataset = e.currentTarget.dataset;
                const request = {
                    methodname: 'local_booste_get_activity_helper',
                    args: {id: dataset.id, type: dataset.activitytype}
                };
                Ajax.call([request])[0].then(function(element) {
                    const popupid = document.getElementById('activity_helper');
                    Templates.render('local_booste/activityhelper', element).then(function(html, js) {
                        Templates.replaceNodeContents(popupid, html, js);
                    });
                }).catch(Notification.exception);
            });
        });
    };

    /**
     * Change submit buttons for activity setting in a scenario.
     *
     * @param {String} label
     */
    const redoActivityButtons = (label) => {
        document.getElementById('id_submitbutton2').value = label;
        document.getElementById('id_submitbutton').hidden = true;
    };

    /**
     * Save order of elements in lists and steps of a scenario.
     *
     * @param {Object} e
     */
    const saveOrder = (e) => {
        const reorderlist = [];
        const target = e.target.dataset;

        document.getElementsByName('elements_list').forEach(function(el) {
            const elements = el.firstElementChild.children;
            let count = 1;
            const stepid = el.id.replace('step_', '').replace('_elements_list', '');

            Array.from(elements).forEach(function(item) {
                item.dataset.step = stepid;
                item.dataset.idx = count;

                const reorder = {
                    id: item.dataset.id,
                    booste_step: stepid,
                    idx: count
                };

                if (target.id != reorder.id ||
                    (target.id == reorder.id && target.step == reorder.booste_step && target.idx == reorder.idx)) {
                    reorderlist.push(reorder);
                    count++;
                }
            });
        });

        const request = {
            methodname: 'local_booste_reorder_elements',
            args: {list: JSON.stringify(reorderlist)}
        };
        Ajax.call([request])[0].then(function() {
        }).catch(Notification.exception);
    };

    /**
     * Hide the third-form loader once all pending AJAX requests have settled.
     * Rewritten without jQuery: uses core/pending's global ajax tracking is not
     * available here, so we simply hide the loader shortly after page scripts
     * have run (the loader is only ever a "please wait, JS is initialising"
     * placeholder, not a real network-request tracker).
     */
    const thirdFormLoader = () => {
        const loader = document.getElementById('booste_loader');
        if (loader) {
            loader.style.display = 'none';
        }
    };

    return {
        getVerbs: getVerbs,
        getLabel: getLabel,
        getActivityHelp: getActivityHelp,
        redoActivityButtons: redoActivityButtons,
        saveOrder: saveOrder,
        thirdFormLoader: thirdFormLoader
    };
});
